private fun parsePath(data: String): Path = PathParser().parsePathString(data).toPath()

/**
 * Логотип со сплэш-анимацией (fillAlpha 0 -> 1 с задержками, как в исходном AVD).
 *
 * @param play запускает анимацию (по умолчанию сразу при появлении на экране)
 * @param onFinished колбэк, вызываемый после того как последняя анимация (path_1/path_3, 500+500мс) завершилась —
 *                   удобно для перехода со сплэша на следующий экран
 */
@Composable
fun MusicLogoSplash(
    modifier: Modifier = Modifier,
    play: Boolean = true,
    onFinished: (() -> Unit)? = null,
) {
    val path2 = remember { parsePath(PATH_2_DATA) } // фиолетовые ноты, #9A27B5
    val path1 = remember { parsePath(PATH_1_DATA) } // бирюзовые ноты, #05A5B5
    val path3 = remember { parsePath(PATH_3_DATA) } // бирюзовый текст, #05A5B5

    var startAnimation by remember { mutableStateOf(false) }
    LaunchedEffect(play) {
        if (play) startAnimation = true
    }

    // startOffset=250, duration=250
    val alphaPath2 by animateFloatAsState(
        targetValue = if (startAnimation) 1f else 0f,
        animationSpec = tween(durationMillis = 250, delayMillis = 250, easing = FastOutLinearInEasing),
        label = "path2Alpha",
    )
    // startOffset=500, duration=500
    val alphaPath1 by animateFloatAsState(
        targetValue = if (startAnimation) 1f else 0f,
        animationSpec = tween(durationMillis = 500, delayMillis = 500, easing = FastOutLinearInEasing),
        label = "path1Alpha",
    )
    // startOffset=500, duration=500
    val alphaPath3 by animateFloatAsState(
        targetValue = if (startAnimation) 1f else 0f,
        animationSpec = tween(durationMillis = 500, delayMillis = 500, easing = FastOutLinearInEasing),
        label = "path3Alpha",
        finishedListener = { onFinished?.invoke() },
    )

    Canvas(modifier = modifier.size(280.dp)) {
        val scale = size.minDimension / VIEWPORT_SIZE
        scale(scale, scale, pivot = Offset.Zero) {
            drawPath(path = path2, color = Color(0xFF9A27B5), alpha = alphaPath2)
            drawPath(path = path1, color = Color(0xFF05A5B5), alpha = alphaPath1)
            drawPath(path = path3, color = Color(0xFF05A5B5), alpha = alphaPath3)
        }
    }
}
